-- Seed: 324 Hyderabad catering services (has_catering_type = yes) from the Places pull.
-- Inserted as status 'sourced' (default) - invisible to consumers until moved to 'live' by admin.

-- The Phase 1 demo vendor collides on slug with a real sourced vendor of the same
-- name below. Rename the demo first so it's unmistakably a placeholder.
update vendors
set name = 'Annapurna Caterers (Demo)', slug = 'annapurna-caterers-demo'
where slug = 'annapurna-caterers';

on conflict (gbp_place_id) do nothing;
